import {esc} from './workspace/ui.mjs';
export async function mountPublicQuestionnaire({container=document.getElementById('questionnaire-public-app'),fetchImpl=fetch,storage=localStorage,win=window}={}){
 const token=new URLSearchParams(win.location.search).get('token')||'';if(!/^[A-Za-z0-9_-]{43}$/.test(token)){container.innerHTML='<section class="qp-card qp-error"><h1>问卷链接无效</h1><p>请向问卷创建者索取完整填写链接。</p></section>';return;}
 const endpoint='/api/questionnaires/public/'+encodeURIComponent(token),key='paperknow-questionnaire-participant:'+token,doneKey=key+':submitted';let participantId=win.crypto.randomUUID(),wasSubmitted=false;try{const existing=storage.getItem(key);if(existing&&/^[A-Za-z0-9_-]{20,100}$/.test(existing))participantId=existing;else storage.setItem(key,participantId);wasSubmitted=storage.getItem(doneKey)==='yes';}catch{}
 const request=async(path,body)=>{const response=await fetchImpl(path,{method:body===undefined?'GET':'POST',credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw Object.assign(Error(value.error||'问卷暂时无法使用'),{status:response.status});return value;};
 try{const data=await request(endpoint),q=data.questionnaire;if(!q||!Array.isArray(q.questions))throw Error('问卷内容无效，请联系创建者。');
  if(wasSubmitted){container.innerHTML='<section class="qp-card qp-success"><span>✓</span><h1>你已提交这份问卷</h1><p>感谢参与，请勿重复填写。</p></section>';return;}
  container.innerHTML=`<section class="qp-card"><div class="qp-eyebrow">自愿参与 · 匿名填写</div><h1>${esc(q.title)}</h1><p class="qp-introduction">${esc(q.introduction)}</p><div class="qp-privacy">${esc(data.privacy)}</div><form id="questionnaire-response-form">${q.questions.map((question,index)=>`<fieldset class="qp-question"><legend>${index+1}. ${esc(question.title)} ${question.required?'<em>必填</em>':'<small>可选</small>'}</legend>${question.type==='text'?`<textarea name="${esc(question.id)}" rows="4" maxlength="2000" ${question.required?'required':''} aria-label="${esc(question.title)}" placeholder="请勿填写姓名、联系方式或其他敏感信息"></textarea>`:question.options.map((option,i)=>`<label class="qp-choice"><input type="${question.type==='multiple'?'checkbox':'radio'}" name="${esc(question.id)}" value="${esc(option)}" ${question.required&&question.type!=='multiple'?'required':''}><span>${esc(option)}</span></label>`).join('')}</fieldset>`).join('')}<label class="qp-consent"><input name="participation-consent" type="checkbox" required> 我了解本问卷为自愿匿名参与，不提交个人敏感信息，同意将本次回答交由问卷创建者用于研究整理。</label><p id="questionnaire-response-status" role="alert" aria-live="polite"></p><button type="submit" class="qp-submit">确认并提交答卷</button><p class="qp-note">同一浏览器对本发布版本限提交一次。答卷提交后无法自行修改，请核对后提交。</p></form></section>`;
  const form=container.querySelector('form'),status=container.querySelector('#questionnaire-response-status');let submitting=false;form.addEventListener('submit',async event=>{event.preventDefault();if(submitting||!form.reportValidity())return;const values=new win.FormData(form),answers={};for(const question of q.questions){const value=question.type==='multiple'?values.getAll(question.id):values.get(question.id)||'';if(question.required&&(!value||Array.isArray(value)&&!value.length)){status.textContent='请完成必填问题：'+question.title;return;}answers[question.id]=value;}submitting=true;const button=form.querySelector('button[type="submit"]');button.disabled=true;status.textContent='正在提交，请稍候…';try{await request(endpoint+'/responses',{participantId,answers,consent:true});try{storage.setItem(doneKey,'yes');}catch{}container.innerHTML='<section class="qp-card qp-success"><span>✓</span><h1>答卷提交成功</h1><p>感谢你的参与。问卷创建者将基于实际答卷进行统计。</p></section>';}catch(error){status.textContent=error.status===409?'此浏览器已提交，或问卷达到收集上限。请勿重复提交，必要时联系问卷创建者。':error.message;button.disabled=false;submitting=false;}});
 }catch(error){container.innerHTML=`<section class="qp-card qp-error"><h1>${error.status===410?'问卷已停止收集':'暂时无法打开问卷'}</h1><p>${esc(error.message)}</p><p>请联系问卷创建者确认链接与收集状态。</p></section>`;}
}
if(typeof document!=='undefined'&&document.getElementById('questionnaire-public-app'))void mountPublicQuestionnaire();
